<template>
  <div class="stories" @touchstart="onTouchStart" @touchend="onTouchEnd">

    <!-- Прогресс бары -->
    <div class="stories__progress">
      <div v-for="(story, i) in stories" :key="i" class="stories__progress-bar">
        <div
          class="stories__progress-fill"
          :style="{
            width: i < currentIndex ? '100%' : i === currentIndex ? progressWidth + '%' : '0%'
          }"
        />
      </div>
    </div>

    <!-- Закрыть -->
    <button class="stories__close" @click="close">
      <svg width="24" height="24" viewBox="0 0 24 24" fill="none">
        <path d="M18 6L6 18M6 6l12 12" stroke="#fff" stroke-width="2" stroke-linecap="round"/>
      </svg>
    </button>

    <!-- Верхняя зелёная часть + картинка -->
    <div class="stories__hero">
      <div class="stories__illustration" v-html="currentStory.svg" />
    </div>

    <!-- Нижняя часть — текст -->
    <div class="stories__content">
      <h2 class="stories__title">{{ currentStory.title }}</h2>
      <p class="stories__text" v-html="currentStory.description" />
    </div>

    <!-- Невидимые зоны тапа (лево/право) -->
    <div class="stories__tap-zones">
      <div class="stories__tap-left"  @click="prev" />
      <div class="stories__tap-right" @click="next" />
    </div>

  </div>
</template>

