const currentIndex = ref(Number(route.query.index) || 0)
const progressWidth = ref(0)
const DURATION = 5000
let progressTimer = null

const currentStory = computed(() => stories[currentIndex.value])

onMounted(() => startTimer())
onUnmounted(() => clearInterval(progressTimer))

function startTimer() {
  clearInterval(progressTimer)
  progressWidth.value = 0
  const step = 100 / (DURATION / 50)
  progressTimer = setInterval(() => {
    progressWidth.value += step
    if (progressWidth.value >= 100) {
      progressWidth.value = 100
      next()
    }
  }, 50)
}

function next() {
  if (currentIndex.value < stories.length - 1) {
    currentIndex.value++
    startTimer()
  } else {
    close()
  }
}

function prev() {
  if (currentIndex.value > 0) {
    currentIndex.value--
    startTimer()
  }
}

function close() {
  clearInterval(progressTimer)
  router.back()
}

let touchStartX = 0
function onTouchStart(e) { touchStartX = e.touches[0].clientX }
function onTouchEnd(e) {
  const diff = e.changedTouches[0].clientX - touchStartX
  if (Math.abs(diff) > 50) diff < 0 ? next() : prev()
}
</script>

